import unittest
from candidate import sort_numbers

class TestSortNumbers(unittest.TestCase):
    def test_normal_case_single_number(self):
        self.assertEqual(sort_numbers('zero'), 'zero')

    def test_normal_case_multiple_numbers(self):
        self.assertEqual(sort_numbers('three one five'), 'one three five')

    def test_normal_case_mixed_numbers(self):
        self.assertEqual(sort_numbers('nine two zero eight'), 'zero two eight nine')

    def test_normal_case_with_duplicates(self):
        self.assertEqual(sort_numbers('five five two'), 'two five five')

    def test_empty_string(self):
        with self.assertRaises(ValueError):
            sort_numbers('')

    def test_none_input(self):
        with self.assertRaises(TypeError):
            sort_numbers(None)

    def test_invalid_word_zero(self):
        with self.assertRaises(ValueError):
            sort_numbers('zero invalid')

    def test_invalid_word_one(self):
        with self.assertRaises(ValueError):
            sort_numbers('one invalid')

    def test_invalid_word_nine(self):
        with self.assertRaises(ValueError):
            sort_numbers('nine invalid')

    def test_invalid_word_unknown(self):
        with self.assertRaises(ValueError):
            sort_numbers('ten')

    def test_boundary_case_single_letter(self):
        self.assertEqual(sort_numbers('one'), 'one')

    def test_boundary_case_all_same(self):
        self.assertEqual(sort_numbers('zero zero zero'), 'zero zero zero')

    def test_boundary_case_all_nine(self):
        self.assertEqual(sort_numbers('nine nine nine'), 'nine nine nine')

    def test_case_sensitivity(self):
        with self.assertRaises(ValueError):
            sort_numbers('ONE')

    def test_whitespace_preservation(self):
        self.assertEqual(sort_numbers('  one   three  '), 'one three')

    def test_mixed_whitespace(self):
        self.assertEqual(sort_numbers('one\tfive\nthree'), 'one three five')
